import {superSchedule} from './super-career-ui.js';
import {displayDate} from './manager-calendar.js';
import {connectedNext,connectedTeam} from './manager-season.js';
import {standings} from './competition.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const connectedCompetitionLabel=id=>({league:'Fantasy league',cup:'Touchline Cup',europe:'European Invitational'}[id]||id);
export function connectedPreview(c){const f=connectedNext(c);return f?`${connectedCompetitionLabel(f.competition)} · ${f.stage||'Matchday '+f.round} · ${displayDate(f.date)} · ${f.home==='user'?'Home':'Away'} vs ${esc(connectedTeam(c,f.home==='user'?f.away:f.home).name)}`:'Season complete';}
export function connectedSchedulePanel(c){
 if(c.careerRulesVersion===2)return superSchedule(c);
 const x=c.connected,next=connectedNext(c),mine=x.calendar.fixtures.filter(f=>f.home==='user'||f.away==='user');
 return `<section class="manager-schedule"><h3>One club. Three competitions.</h3><p>Connected fantasy career · original Touchline Cup and a European Invitational using the modern 36-team format. These are not the FA Cup or a verified domestic/UCL career. Dates and European invitations are authored game rules; all 20 domestic clubs enter the cup.</p><p><b>Next: ${connectedPreview(c)}</b></p><p>Recovery follows elapsed days. Wages are charged once per calendar week. Fantasy registration windows: August and January. Upcoming knockout ties appear after the preceding round.</p><details open><summary>Your calendar · ${mine.filter(f=>f.status==='complete').length} recorded / ${mine.length} currently scheduled</summary><div class="manager-fixture-scroll">${mine.map(f=>{const home=f.home==='user',team=connectedTeam(c,home?f.away:f.home),r=f.result;return `<div class="fixture ${f.id===next?.id?'mine':''}"><span>${displayDate(f.date)}<small> · ${home?'H':'A'} · ${connectedCompetitionLabel(f.competition)}${f.stage?' · '+esc(f.stage):''}</small></span><strong>${esc(team.name)}</strong><span>${r?(home?r.score:[...r.score].reverse()).join('–')+(r.pens?' (pens)':''):'Upcoming'}</span>${r?.definition?`<button class="btn ghost" data-action="eu-connected-replay" data-value="${f.id}">Replay</button>`:''}</div>`;}).join('')}</div></details><h3>Cup journey</h3><p>${x.cup.champion?'Champion: '+esc(connectedTeam(c,x.cup.champion).name):'Next round: '+(x.cup.round+1)+' · '+x.cup.remaining.length+' clubs remain'}</p>${x.cup.results.filter(r=>r.home==='user'||r.away==='user').map(r=>`<p>${esc(r.stage)} · ${r.score.join('–')}${r.pens?' · penalties '+r.pens.join('–'):''}</p>`).join('')}<h3>European Invitational</h3><p>${x.europe.champion?'Champion: '+esc(connectedTeam(c,x.europe.champion).name):esc(x.europe.stage)+' · '+(x.europe.knockoutLeg===2?'second leg next':'next round scheduled')}. Eight league opponents; two-legged ties and one final. Every season is invitational, without a claim of real UEFA qualification.</p><details><summary>European table and results</summary><div class="eu-table-wrap"><table class="league-table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>Pts</th></tr></thead><tbody>${standings(x.europe).map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.p}</td><td>${t.pts}</td></tr>`).join('')}</tbody></table></div>${x.europe.results.filter(r=>r.home==='user'||r.away==='user').map(r=>`<p>${esc(r.stage)} · leg ${r.leg} · ${r.score.join('–')}${r.aggregate?' · aggregate '+r.aggregate.join('–'):''}</p>`).join('')}</details>${x.review?`<h3>Season review</h3><p>League finish: ${x.review.rank}. ${x.review.fixtures} club fixtures played. Cup winner: ${esc(x.review.cupWinner)}. European winner: ${esc(x.review.europeWinner)}.</p>`:''}</section>`;
}
